<script setup>
import {ask} from './ui'
import {ref,onMounted} from 'vue'
const props=defineProps({api:Function})
const open=ref(true),items=ref([]),editing=ref(null),busy=ref(false),error=ref(''),notice=ref('')
async function load(){try{open.value=(await props.api('/site')).registration_open;items.value=(await props.api('/admin/announcements')).items}catch(e){error.value=e.message}}
async function registration(){if(!await ask(open.value?'关闭公开注册？已有用户仍可正常登录。':'开启公开注册？访客将可以自行创建账号。'))return;busy.value=true;error.value='';try{await props.api('/admin/site',{method:'PUT',body:JSON.stringify({registration_open:!open.value})});open.value=!open.value;notice.value='注册设置已保存'}catch(e){error.value=e.message}finally{busy.value=false}}
function edit(a){editing.value=a?{...a,published:!!a.published,popup:!!a.popup,once_only:!!a.once_only}:{id:crypto.randomUUID().replaceAll('-',''),title:'',body:'',published:false,popup:true,once_only:true};error.value=''}
async function publication(a){if(busy.value||!await ask(a.published?'撤下这条公告？用户端将不再显示。':'发布这条公告？'))return;busy.value=true;error.value='';try{await props.api('/admin/announcements/'+a.id+'/publication',{method:'PATCH',body:JSON.stringify({published:!a.published})});notice.value=a.published?'公告已撤下':'公告已发布';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{await props.api('/admin/announcements/'+editing.value.id,{method:'PUT',body:JSON.stringify(editing.value)});editing.value=null;notice.value='公告已保存';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p>
<section class="simple-panel"><div class="simple-panel-title"><h3>开放注册</h3><button class="button" :disabled="busy" @click="registration">{{open?'关闭公开注册':'开启公开注册'}}</button></div><p class="description">当前{{open?'允许':'不允许'}}访客自行注册。关闭后，已有用户可继续登录，管理员仍可创建用户。</p></section>
<section class="simple-panel notice-panel"><div class="simple-panel-title"><h3>公告管理</h3><button class="button primary" @click="edit(null)">新增公告</button></div><p class="description">公告以纯文本展示。发布后用户可查看；启用弹窗时，用户登录后会收到提示。编辑保存会更新版本，“只提示一次”按公告版本计算。</p><div v-for="a in items" :key="a.id" class="notice-row"><div><strong>{{a.title}}</strong><small>{{a.published?'已发布':'未发布'}} · {{a.popup?'弹窗提示':'仅公告列表'}} · {{a.once_only?'每个版本提示一次':'每次登录提示'}}</small></div><button class="text-button" :disabled="busy" @click="edit(a)">编辑</button><button class="button" :disabled="busy" @click="publication(a)">{{a.published?'撤下':'发布'}}</button></div><div v-if="!items.length" class="empty-state"><p>暂无公告</p></div></section>
<div v-if="editing" class="notice-overlay"><section class="notice-editor" role="dialog" aria-modal="true" aria-label="编辑公告"><h3>{{items.some(a=>a.id===editing.id)?'编辑公告':'新增公告'}}</h3><form @submit.prevent="save"><label>标题<input v-model="editing.title" maxlength="120" required></label><label>内容<textarea v-model="editing.body" rows="9" maxlength="10000" required></textarea></label><label class="check"><input type="checkbox" v-model="editing.published">发布公告</label><label class="check"><input type="checkbox" v-model="editing.popup">登录后弹窗提示</label><label class="check"><input type="checkbox" v-model="editing.once_only">每个版本只提示一次</label><p v-if="error" role="alert">{{error}}</p><footer><button class="button" type="button" :disabled="busy" @click="editing=null">取消</button><button class="button primary" :disabled="busy">{{busy?'保存中…':'保存公告'}}</button></footer></form></section></div></template>
<style scoped>
.notice-panel{margin-top:22px}.description{padding:16px 22px;font-size:12px;line-height:1.9;color:#89929f}.notice-row{display:flex;align-items:center;gap:18px;padding:18px 22px;border-top:1px solid #edf0f4}.notice-row>div{flex:1}.notice-row strong{font-size:13px}.notice-row small{display:block;color:#929ba6;font-size:11px;margin-top:8px}.success{font-size:13px;color:#378562;margin-bottom:16px}.notice-overlay{position:fixed;inset:0;background:#1c25336e;z-index:100;display:grid;place-items:center;padding:16px}.notice-editor{background:#fff;padding:26px;border-radius:16px;width:min(620px,100%);max-height:90dvh;overflow:auto}.notice-editor label{display:grid;gap:8px;font-size:13px;margin-top:16px}.notice-editor input:not([type=checkbox]),textarea{padding:11px;border:1px solid #dfe4eb;border-radius:8px;width:100%;box-sizing:border-box;font:inherit}.notice-editor .check{display:flex;align-items:center;gap:8px}.notice-editor footer{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}
</style>
